fn equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since a and b have the same length, we can iterate over them together
    // and compare each pair of elements.
    a.iter()
        .zip(b.iter())
        .map(|(x, y)| x == y)
        .collect()
}